insert into public.wsp_frameworks (id, slug, name, description, publisher)
insert into public.wsp_framework_versions (id, framework_id, version, status)
insert into public.wsp_skills (id, framework_id, framework_version, code, name, description) values
  ('wts:s01c01', 'framework:wts', '1', 'WTS-S01.C01', 'Identifier les principaux acteurs du marché futures', 'Nommer les grandes catégories d''acteurs présents sur les marchés futures et comprendre l''influence de leurs comportements sur le prix.'),
  ('wts:s01c02', 'framework:wts', '1', 'WTS-S01.C02', 'Expliquer le rôle du carnet d''ordres', 'Comprendre ce que représente le carnet d''ordres, ce qu''il montre de l''offre et de la demande, et ses limites d''interprétation.'),
  ('wts:s01c03', 'framework:wts', '1', 'WTS-S01.C03', 'Distinguer ordre limite, ordre marché et ordre stop', 'Comprendre le fonctionnement et les usages respectifs des ordres limite, marché et stop, et leurs conséquences sur l''exécution.'),
  ('wts:s01c04', 'framework:wts', '1', 'WTS-S01.C04', 'Reconnaître les contrats futures tradés à l''école', 'Identifier les contrats futures utilisés dans le cadre de la formation et leurs caractéristiques principales.'),
  ('wts:s01c05', 'framework:wts', '1', 'WTS-S01.C05', 'Comprendre tick, taille de point et valeur du contrat', 'Maîtriser les unités de cotation (tick, point) et la valeur monétaire associée à un contrat, base de tout calcul de risque.'),
  ('wts:s01c06', 'framework:wts', '1', 'WTS-S01.C06', 'Lire les volumes échangés sur une séance', 'Comprendre ce que représentent les volumes échangés et ce qu''ils révèlent de l''activité et de l''intérêt sur une séance.'),
  ('wts:s01c07', 'framework:wts', '1', 'WTS-S01.C07', 'Comprendre la liquidité disponible et absorbée', 'Distinguer la liquidité présente (disponible) de la liquidité consommée (absorbée) et comprendre ce que ces dynamiques indiquent.'),
  ('wts:s01c08', 'framework:wts', '1', 'WTS-S01.C08', 'Identifier les horaires clés des marchés futures', 'Connaître les moments structurants de la séance (ouvertures, chevauchements, annonces) et leur effet sur l''activité.'),
  ('wts:s01c09', 'framework:wts', '1', 'WTS-S01.C09', 'Différencier tendance, range et rotation', 'Reconnaître les grands régimes de marché (tendance, range, rotation) et comprendre ce que chacun implique pour l''action.'),
  ('wts:s01c10', 'framework:wts', '1', 'WTS-S01.C10', 'Expliquer les bases du Market Profile et Volume Profile', 'Comprendre et expliquer les notions fondamentales du Market Profile et du Volume Profile (POC, Value Area, zones de volume) et leur usage.'),
  ('wts:s02c01', 'framework:wts', '1', 'WTS-S02.C01', 'Identifier la structure de marché intraday', 'Lire l''organisation du prix au cours de la séance (impulsions, corrections, points pivots) pour situer l''action dans son contexte.'),
  ('wts:s02c02', 'framework:wts', '1', 'WTS-S02.C02', 'Repérer les zones de liquidité visibles', 'Identifier sur un graphique les zones où la liquidité est concentrée (extrêmes de séance, niveaux de rejet) et en comprendre l''implication.'),
  ('wts:s02c03', 'framework:wts', '1', 'WTS-S02.C03', 'Repérer les zones de faible volume', 'Identifier les zones traversées rapidement par le prix (faible volume) et comprendre leur rôle de zones de transition.'),
  ('wts:s02c04', 'framework:wts', '1', 'WTS-S02.C04', 'Identifier le VPOC et ses déplacements', 'Repérer le point de contrôle de volume (VPOC) et suivre ses déplacements comme indice de l''équilibre du marché.'),
  ('wts:s02c05', 'framework:wts', '1', 'WTS-S02.C05', 'Identifier les zones de rejet du prix', 'Repérer les niveaux où le prix a été nettement rejeté et comprendre ce que ces rejets révèlent de l''intérêt des acteurs.'),
  ('wts:s02c06', 'framework:wts', '1', 'WTS-S02.C06', 'Lire l''équilibre et le déséquilibre du marché', 'Reconnaître les phases d''équilibre (rotation autour d''une valeur) et de déséquilibre (recherche directionnelle) du marché.'),
  ('wts:s02c07', 'framework:wts', '1', 'WTS-S02.C07', 'Repérer les doubles distributions', 'Identifier les séances où le prix forme deux zones de valeur distinctes (double distribution) et en comprendre l''implication.'),
  ('wts:s02c08', 'framework:wts', '1', 'WTS-S02.C08', 'Distinguer acceptation et rejet d''un niveau', 'Faire la différence entre un niveau accepté (le prix y reste et échange) et un niveau rejeté (le prix le quitte vite).'),
  ('wts:s02c09', 'framework:wts', '1', 'WTS-S02.C09', 'Identifier les niveaux de réaction récurrents', 'Repérer les niveaux de prix où le marché réagit de façon répétée et comprendre leur valeur de référence.'),
  ('wts:s02c10', 'framework:wts', '1', 'WTS-S02.C10', 'Lire le contexte avant l''ouverture US', 'Analyser les éléments de contexte (séances précédentes, niveaux, biais) avant l''ouverture américaine pour aborder la séance préparé.'),
  ('wts:s02c11', 'framework:wts', '1', 'WTS-S02.C11', 'Relier volume, prix et temps dans l''analyse', 'Intégrer les trois dimensions volume, prix et temps dans une lecture cohérente plutôt que de les considérer isolément.'),
  ('wts:s02c12', 'framework:wts', '1', 'WTS-S02.C12', 'Formuler un biais de marché observable', 'Exprimer un biais directionnel (haussier, baissier, neutre) fondé sur des éléments observables et non sur une intuition.'),
  ('wts:s03c01', 'framework:wts', '1', 'WTS-S03.C01', 'Construire un scénario principal avant session', 'Élaborer, avant la séance, un scénario principal cohérent décrivant l''évolution attendue et les conditions associées.'),
  ('wts:s03c02', 'framework:wts', '1', 'WTS-S03.C02', 'Construire un scénario alternatif avant session', 'Prévoir, avant la séance, un scénario alternatif au cas où le scénario principal serait invalidé, pour ne pas être pris au dépourvu.'),
  ('wts:s03c03', 'framework:wts', '1', 'WTS-S03.C03', 'Définir les zones d''intervention autorisées', 'Délimiter à l''avance les zones où une prise de position est autorisée par le plan, pour cadrer l''action.'),
  ('wts:s03c04', 'framework:wts', '1', 'WTS-S03.C04', 'Définir les zones d''invalidation du scénario', 'Fixer à l''avance les conditions ou niveaux qui invalident un scénario, pour savoir quand renoncer.'),
  ('wts:s03c05', 'framework:wts', '1', 'WTS-S03.C05', 'Prioriser les zones selon le contexte', 'Hiérarchiser les zones d''intérêt selon leur pertinence dans le contexte du jour, plutôt que de les traiter également.'),
  ('wts:s03c06', 'framework:wts', '1', 'WTS-S03.C06', 'Préparer un plan d''action avant l''entrée', 'Formaliser, avant d''agir, un plan d''action complet (conditions d''entrée, de sortie, de gestion) pour ne pas décider dans l''urgence.'),
  ('wts:s03c07', 'framework:wts', '1', 'WTS-S03.C07', 'Adapter le scénario après nouvelle information', 'Réviser un scénario de façon raisonnée quand une information nouvelle et significative apparaît, sans sur-réagir au bruit.'),
  ('wts:s03c08', 'framework:wts', '1', 'WTS-S03.C08', 'Distinguer décision planifiée et réaction impulsive', 'Reconnaître la différence entre une décision issue du plan et une réaction impulsive, et privilégier la première.'),
  ('wts:s03c09', 'framework:wts', '1', 'WTS-S03.C09', 'Documenter le scénario dans le journal', 'Consigner son scénario de façon claire et exploitable dans un journal, pour permettre l''analyse a posteriori.'),
  ('wts:s03c10', 'framework:wts', '1', 'WTS-S03.C10', 'Revoir le scénario après session', 'Analyser, après la séance, l''écart entre le scénario prévu et ce qui s''est passé, pour en tirer des enseignements.'),
  ('wts:s04c01', 'framework:wts', '1', 'WTS-S04.C01', 'Décrire un setup avec conditions d''entrée', 'Formuler un setup de façon claire : le contexte, les conditions d''entrée précises et ce qui le déclenche.'),
  ('wts:s04c02', 'framework:wts', '1', 'WTS-S04.C02', 'Définir les conditions d''invalidation du setup', 'Préciser à l''avance ce qui rend un setup non valable, pour éviter de le forcer quand le contexte ne convient pas.'),
  ('wts:s04c03', 'framework:wts', '1', 'WTS-S04.C03', 'Définir le contexte requis pour utiliser un setup', 'Préciser les conditions de marché dans lesquelles un setup est pertinent, car un setup n''est pas valable en toute circonstance.'),
  ('wts:s04c04', 'framework:wts', '1', 'WTS-S04.C04', 'Identifier les setups non autorisés', 'Reconnaître les configurations que le plan interdit (hors méthode, hors contexte) pour ne pas s''y engager.'),
  ('wts:s04c05', 'framework:wts', '1', 'WTS-S04.C05', 'Tester un setup sur plusieurs sessions', 'Évaluer la pertinence d''un setup en l''observant sur un nombre suffisant de sessions avant de s''y fier.'),
  ('wts:s04c06', 'framework:wts', '1', 'WTS-S04.C06', 'Distinguer setup théorique et setup exécutable', 'Faire la différence entre un setup séduisant sur le papier et un setup réellement exécutable dans ses conditions.'),
  ('wts:s04c07', 'framework:wts', '1', 'WTS-S04.C07', 'Filtrer les entrées hors contexte', 'Écarter les opportunités d''entrée qui ne correspondent pas au contexte défini, pour ne prendre que les entrées valides.'),
  ('wts:s04c08', 'framework:wts', '1', 'WTS-S04.C08', 'Mesurer la fréquence d''apparition d''un setup', 'Estimer à quelle fréquence un setup se présente réellement, pour ajuster ses attentes et son activité.'),
  ('wts:s04c09', 'framework:wts', '1', 'WTS-S04.C09', 'Associer un setup à une preuve visuelle', 'Illustrer un setup par des exemples visuels clairs, pour le rendre reconnaissable et vérifiable.'),
  ('wts:s04c10', 'framework:wts', '1', 'WTS-S04.C10', 'Documenter les erreurs liées au setup', 'Consigner les erreurs commises en lien avec un setup pour en tirer des enseignements et progresser.'),
  ('wts:s04c11', 'framework:wts', '1', 'WTS-S04.C11', 'Ajuster un setup sans changer de méthode', 'Améliorer un setup à la marge sans renier sa méthode globale, pour progresser sans se disperser.'),
  ('wts:s04c12', 'framework:wts', '1', 'WTS-S04.C12', 'Présenter un setup au coach avec preuves', 'Exposer un setup de façon structurée et étayée par des preuves, pour permettre au coach de l''évaluer.'),
  ('wts:s05c01', 'framework:wts', '1', 'WTS-S05.C01', 'Rédiger une recette de trading personnelle', 'Formaliser par écrit son cadre de trading complet (méthode, règles, limites), pour agir selon un plan stable.'),
  ('wts:s05c02', 'framework:wts', '1', 'WTS-S05.C02', 'Définir les marchés autorisés', 'Préciser sur quels marchés on s''autorise à trader, pour concentrer son attention et sa compétence.'),
  ('wts:s05c03', 'framework:wts', '1', 'WTS-S05.C03', 'Définir les horaires autorisés', 'Fixer les plages horaires où l''on s''autorise à trader, pour éviter les moments défavorables.'),
  ('wts:s05c04', 'framework:wts', '1', 'WTS-S05.C04', 'Définir les conditions d''absence de trade', 'Préciser à l''avance les situations où il vaut mieux ne pas trader (no-trade), car ne rien faire est parfois la bonne décision.'),
  ('wts:s05c05', 'framework:wts', '1', 'WTS-S05.C05', 'Définir les règles de gestion de position', 'Établir des règles claires pour gérer une position ouverte (renforcement, allègement, déplacement du stop).'),
  ('wts:s05c06', 'framework:wts', '1', 'WTS-S05.C06', 'Définir les règles de sortie', 'Établir à l''avance comment et quand sortir d''une position (objectif, invalidation, temps), pour ne pas décider dans l''émotion.'),
  ('wts:s05c07', 'framework:wts', '1', 'WTS-S05.C07', 'Définir les règles de stop session', 'Fixer les limites qui arrêtent la séance (perte max, nombre de trades, événement), pour se protéger.'),
  ('wts:s05c08', 'framework:wts', '1', 'WTS-S05.C08', 'Maintenir une checklist avant session', 'Utiliser systématiquement une checklist de préparation avant de trader, pour aborder chaque séance prêt.'),
  ('wts:s05c09', 'framework:wts', '1', 'WTS-S05.C09', 'Vérifier la cohérence entre setup et recette', 'S''assurer que ses setups sont bien alignés avec sa recette globale, pour éviter les contradictions internes.'),
  ('wts:s05c10', 'framework:wts', '1', 'WTS-S05.C10', 'Mettre à jour la recette après validation coach', 'Faire évoluer sa recette de façon contrôlée, après validation du coach, pour progresser sans dérive.'),
  ('wts:s05c11', 'framework:wts', '1', 'WTS-S05.C11', 'Respecter une version publiée de sa recette', 'S''en tenir à la version en vigueur de sa recette sans la modifier en cours de séance, pour garantir la discipline.'),
  ('wts:s06c01', 'framework:wts', '1', 'WTS-S06.C01', 'Attendre la zone prévue avant d''intervenir', 'Ne pas agir tant que le prix n''a pas atteint la zone définie dans le plan, pour n''intervenir que là où c''est prévu.'),
  ('wts:s06c02', 'framework:wts', '1', 'WTS-S06.C02', 'Attendre le signal prévu avant d''entrer', 'N''entrer qu''après l''apparition du signal défini dans le plan, sans devancer le déclencheur.'),
  ('wts:s06c03', 'framework:wts', '1', 'WTS-S06.C03', 'Exécuter sans anticiper le signal', 'Maintenir l''exécution strictement après le déclencheur, sans agir sur une intuition ou une anticipation.'),
  ('wts:s06c04', 'framework:wts', '1', 'WTS-S06.C04', 'Placer le stop selon la règle prévue', 'Positionner le stop de protection exactement là où la règle du plan le prévoit, sans le déplacer par confort.'),
  ('wts:s06c05', 'framework:wts', '1', 'WTS-S06.C05', 'Respecter la taille prévue', 'Prendre la taille de position définie par le plan, sans la gonfler par excès de confiance ni la réduire par peur.'),
  ('wts:s06c06', 'framework:wts', '1', 'WTS-S06.C06', 'Saisir l''ordre sans erreur opérationnelle', 'Passer ses ordres proprement, sans erreur de manipulation (sens, taille, prix, type), pour que l''intention soit fidèlement exécutée.'),
  ('wts:s06c07', 'framework:wts', '1', 'WTS-S06.C07', 'Gérer l''entrée sans déplacer le risque', 'Une fois en position, ne pas augmenter le risque prévu (élargir le stop, moyenner à perte) pour éviter la perte planifiée.'),
  ('wts:s06c08', 'framework:wts', '1', 'WTS-S06.C08', 'Gérer la sortie selon le plan', 'Sortir de position conformément aux règles du plan (objectif, invalidation, temps), sans improviser.'),
  ('wts:s06c09', 'framework:wts', '1', 'WTS-S06.C09', 'Éviter les entrées hors contexte', 'Ne pas entrer quand le contexte du plan n''est pas réuni, même si une opportunité apparente se présente.'),
  ('wts:s06c10', 'framework:wts', '1', 'WTS-S06.C10', 'Éviter les reprises immédiates non planifiées', 'Ne pas ré-entrer impulsivement juste après une sortie ou une perte, hors de tout plan (revenge trading).'),
  ('wts:s06c11', 'framework:wts', '1', 'WTS-S06.C11', 'Respecter le nombre maximal de trades', 'S''en tenir au nombre de trades maximal fixé par le plan, pour éviter le sur-trading.'),
  ('wts:s06c12', 'framework:wts', '1', 'WTS-S06.C12', 'Respecter la fenêtre horaire autorisée', 'Trader uniquement pendant la fenêtre horaire prévue par le plan, sans déborder.'),
  ('wts:s06c13', 'framework:wts', '1', 'WTS-S06.C13', 'Identifier une mauvaise exécution après coup', 'Reconnaître, à l''analyse post-séance, les exécutions qui n''ont pas respecté le plan, pour pouvoir les corriger.'),
  ('wts:s06c14', 'framework:wts', '1', 'WTS-S06.C14', 'Corriger une erreur d''exécution documentée', 'Mettre en place une correction concrète suite à une erreur d''exécution identifiée, pour qu''elle ne se reproduise pas.'),
  ('wts:s06c15', 'framework:wts', '1', 'WTS-S06.C15', 'Maintenir la qualité d''exécution sous pression', 'Conserver une exécution conforme au plan même dans les moments difficiles (stress, perte, forte volatilité).'),
  ('wts:s06c16', 'framework:wts', '1', 'WTS-S06.C16', 'Arrêter la session selon la règle définie', 'Cesser de trader quand la règle d''arrêt de session est atteinte, sans chercher à continuer.'),
  ('wts:s06c17', 'framework:wts', '1', 'WTS-S06.C17', 'Appliquer une pause après perte', 'S''imposer une pause après une perte, pour éviter les décisions à chaud et retrouver son calme.'),
  ('wts:s06c18', 'framework:wts', '1', 'WTS-S06.C18', 'Appliquer une pause après gain important', 'S''imposer une pause après un gain important, pour éviter l''excès de confiance et le relâchement.'),
  ('wts:s06c19', 'framework:wts', '1', 'WTS-S06.C19', 'Exécuter en simulateur avec discipline', 'Traiter les séances en simulateur avec le même sérieux et la même discipline qu''en réel.'),
  ('wts:s06c20', 'framework:wts', '1', 'WTS-S06.C20', 'Exécuter en réel avec discipline contrôlée', 'Passer au trading réel en conservant la discipline acquise, malgré l''enjeu émotionnel supplémentaire.'),
  ('wts:s06c21', 'framework:wts', '1', 'WTS-S06.C21', 'Distinguer opportunité valide et impulsion', 'Faire la différence, au moment d''agir, entre une opportunité conforme au plan et une impulsion à écarter.'),
  ('wts:s06c22', 'framework:wts', '1', 'WTS-S06.C22', 'Préparer l''ordre avant l''entrée', 'Préparer les paramètres de l''ordre (niveau, taille, stop, cible) avant le moment d''entrer, pour agir sans précipitation.'),
  ('wts:s06c23', 'framework:wts', '1', 'WTS-S06.C23', 'Réduire les clics inutiles pendant session', 'Limiter les interventions superflues sur l''interface pendant la séance, signe d''agitation ou de sur-gestion.'),
  ('wts:s06c24', 'framework:wts', '1', 'WTS-S06.C24', 'Produire une preuve d''exécution exploitable', 'Conserver des traces d''exécution claires et exploitables (captures, exports) permettant l''analyse et la validation.'),
  ('wts:s07c01', 'framework:wts', '1', 'WTS-S07.C01', 'Définir le risque maximal par trade', 'Fixer le montant ou pourcentage maximal que l''on accepte de perdre sur un seul trade, base de toute gestion du risque.'),
  ('wts:s07c02', 'framework:wts', '1', 'WTS-S07.C02', 'Calculer la perte maximale de la session', 'Déterminer à l''avance la perte totale au-delà de laquelle on arrête la séance, pour protéger le capital.'),
  ('wts:s07c03', 'framework:wts', '1', 'WTS-S07.C03', 'Respecter le stop initial', 'Laisser le stop de protection à son niveau initial défini, sans l''élargir pour éviter d''être stoppé.'),
  ('wts:s07c04', 'framework:wts', '1', 'WTS-S07.C04', 'Ne pas augmenter le risque après perte', 'Résister à la tentation d''augmenter la taille ou le risque après une perte pour se refaire.'),
  ('wts:s07c05', 'framework:wts', '1', 'WTS-S07.C05', 'Réduire la taille après drawdown', 'Diminuer sa taille de position après une série de pertes (drawdown), pour préserver le capital et se reconstruire.'),
  ('wts:s07c06', 'framework:wts', '1', 'WTS-S07.C06', 'Arrêter après limite de pertes', 'Cesser de trader dès que la limite de pertes définie est atteinte, sans chercher à se rattraper.'),
  ('wts:s07c07', 'framework:wts', '1', 'WTS-S07.C07', 'Identifier une séquence de pertes dangereuse', 'Reconnaître quand une série de pertes devient dangereuse pour le capital ou le mental, pour réagir à temps.'),
  ('wts:s07c08', 'framework:wts', '1', 'WTS-S07.C08', 'Séparer analyse du marché et récupération de perte', 'Ne pas laisser le besoin de récupérer une perte contaminer l''analyse du marché, qui doit rester objective.'),
  ('wts:s07c09', 'framework:wts', '1', 'WTS-S07.C09', 'Mesurer le drawdown de la période', 'Calculer et suivre le drawdown (baisse maximale du capital) sur une période, pour connaître son exposition réelle.'),
  ('wts:s07c10', 'framework:wts', '1', 'WTS-S07.C10', 'Suivre le ratio gain moyen / perte moyenne', 'Calculer et suivre le rapport entre gain moyen et perte moyenne, indicateur pédagogique de la qualité de gestion.'),
  ('wts:s07c11', 'framework:wts', '1', 'WTS-S07.C11', 'Suivre le profit factor comme indicateur pédagogique', 'Comprendre et suivre le profit factor comme repère de progression, sans en faire une obsession de performance.'),
  ('wts:s07c12', 'framework:wts', '1', 'WTS-S07.C12', 'Comprendre l''impact des frais et commissions', 'Prendre en compte les frais et commissions dans l''évaluation de sa performance et de son risque réel.'),
  ('wts:s07c13', 'framework:wts', '1', 'WTS-S07.C13', 'Adapter la taille au niveau de maîtrise', 'Ajuster sa taille de position à son niveau réel de maîtrise, sans sur-dimensionner par rapport à sa compétence.'),
  ('wts:s07c14', 'framework:wts', '1', 'WTS-S07.C14', 'Protéger le capital d''apprentissage', 'Préserver le capital dédié à l''apprentissage comme une ressource limitée, en évitant les risques inconsidérés.'),
  ('wts:s07c15', 'framework:wts', '1', 'WTS-S07.C15', 'Définir une règle de reprise après pause', 'Établir une règle claire pour reprendre le trading après une pause (perte, drawdown, arrêt), afin de revenir en conditions maîtrisées.'),
  ('wts:s07c16', 'framework:wts', '1', 'WTS-S07.C16', 'Documenter chaque dépassement de risque', 'Consigner tout dépassement de la règle de risque, pour en analyser la cause et l''empêcher de se reproduire.'),
  ('wts:s07c17', 'framework:wts', '1', 'WTS-S07.C17', 'Corriger un dépassement de risque avec preuve', 'Mettre en place une correction concrète suite à un dépassement de risque documenté, et le prouver.'),
  ('wts:s07c18', 'framework:wts', '1', 'WTS-S07.C18', 'Maintenir le risque stable sur plusieurs sessions', 'Conserver un niveau de risque constant et maîtrisé d''une session à l''autre, sans à-coups liés aux émotions.'),
  ('wts:s07c19', 'framework:wts', '1', 'WTS-S07.C19', 'Identifier les contextes où le risque augmente', 'Reconnaître les situations (émotion, fatigue, marché particulier) où l''on tend à prendre plus de risque, pour s''en prémunir.'),
  ('wts:s07c20', 'framework:wts', '1', 'WTS-S07.C20', 'Présenter au coach une revue de risque', 'Exposer au coach une revue structurée de sa gestion du risque, étayée par des données, pour être évalué et progresser.'),
  ('wts:s08c01', 'framework:wts', '1', 'WTS-S08.C01', 'Remplir le journal après chaque session', 'Tenir un journal de trading complet après chaque séance, base de toute auto-analyse et de tout suivi.'),
  ('wts:s08c02', 'framework:wts', '1', 'WTS-S08.C02', 'Importer les résultats trading dans le système', 'Consolider ses résultats de trading dans son système de suivi, pour disposer de données exploitables.'),
  ('wts:s08c03', 'framework:wts', '1', 'WTS-S08.C03', 'Taguer l''erreur dominante de la session', 'Identifier et étiqueter l''erreur principale de chaque session, pour faire ressortir les tendances.'),
  ('wts:s08c04', 'framework:wts', '1', 'WTS-S08.C04', 'Rédiger une autopsie de trade perdant', 'Analyser en profondeur un trade perdant (décision, exécution, contexte) pour en tirer un enseignement.'),
  ('wts:s08c05', 'framework:wts', '1', 'WTS-S08.C05', 'Rédiger une autopsie de trade gagnant', 'Analyser un trade gagnant pour distinguer ce qui relève du process maîtrisé de ce qui relève de la chance.'),
  ('wts:s08c06', 'framework:wts', '1', 'WTS-S08.C06', 'Comparer plan prévu et exécution réelle', 'Confronter systématiquement ce qui était prévu au plan à ce qui a été réellement exécuté, pour mesurer l''écart.'),
  ('wts:s08c07', 'framework:wts', '1', 'WTS-S08.C07', 'Identifier une erreur récurrente sur plusieurs sessions', 'Repérer les erreurs qui reviennent d''une session à l''autre, pour les traiter en priorité.'),
  ('wts:s08c08', 'framework:wts', '1', 'WTS-S08.C08', 'Préparer un bilan hebdomadaire structuré', 'Produire chaque semaine un bilan structuré de sa pratique (résultats, erreurs, progrès, priorités).'),
  ('wts:s08c09', 'framework:wts', '1', 'WTS-S08.C09', 'Préparer un coaching avec preuves', 'Arriver à une séance de coaching avec des preuves et questions préparées, pour un accompagnement efficace.'),
  ('wts:s08c10', 'framework:wts', '1', 'WTS-S08.C10', 'Transformer une erreur en action corrective', 'Convertir une erreur identifiée en une action corrective concrète et suivie, pour boucler la boucle d''apprentissage.'),
  ('wts:s09c01', 'framework:wts', '1', 'WTS-S09.C01', 'Identifier son état émotionnel avant session', 'Reconnaître et nommer son état émotionnel avant de trader, pour en tenir compte dans sa décision de trader ou non.'),
  ('wts:s09c02', 'framework:wts', '1', 'WTS-S09.C02', 'Identifier le FOMO pendant session', 'Reconnaître, en séance, la peur de manquer une opportunité (FOMO) et son effet sur ses décisions.'),
  ('wts:s09c03', 'framework:wts', '1', 'WTS-S09.C03', 'Identifier le revenge trading après perte', 'Reconnaître la pulsion de reprendre pour se venger d''une perte, et son caractère destructeur.'),
  ('wts:s09c04', 'framework:wts', '1', 'WTS-S09.C04', 'Identifier l''euphorie après gain', 'Reconnaître l''état d''euphorie après un gain et le relâchement de discipline qu''il peut provoquer.'),
  ('wts:s09c05', 'framework:wts', '1', 'WTS-S09.C05', 'Respecter une pause émotionnelle', 'S''imposer une pause quand l''émotion monte, pour éviter d''agir sous son emprise.'),
  ('wts:s09c06', 'framework:wts', '1', 'WTS-S09.C06', 'Exécuter malgré l''inconfort sans forcer', 'Agir selon son plan malgré un inconfort normal, tout en distinguant l''inconfort acceptable du signal qu''il ne faut pas forcer.'),
  ('wts:s09c07', 'framework:wts', '1', 'WTS-S09.C07', 'Renoncer à une opportunité hors plan', 'Accepter de laisser passer une opportunité qui n''est pas dans le plan, sans regret ni contournement.'),
  ('wts:s09c08', 'framework:wts', '1', 'WTS-S09.C08', 'Accepter une perte conforme au plan', 'Accepter sereinement une perte qui respecte le plan, comme une composante normale du trading.'),
  ('wts:s09c09', 'framework:wts', '1', 'WTS-S09.C09', 'Ne pas chercher à se refaire immédiatement', 'Résister à l''envie de récupérer immédiatement une perte, qui pousse à des décisions hors plan.'),
  ('wts:s09c10', 'framework:wts', '1', 'WTS-S09.C10', 'Maintenir la patience dans une zone d''attente', 'Conserver sa patience pendant les phases d''attente, sans forcer une action par ennui ou impatience.'),
  ('wts:s09c11', 'framework:wts', '1', 'WTS-S09.C11', 'Maintenir la neutralité après série de pertes', 'Rester émotionnellement neutre et fidèle à son plan après plusieurs pertes consécutives.'),
  ('wts:s09c12', 'framework:wts', '1', 'WTS-S09.C12', 'Maintenir la neutralité après série de gains', 'Rester émotionnellement neutre et discipliné après plusieurs gains, sans excès de confiance.'),
  ('wts:s09c13', 'framework:wts', '1', 'WTS-S09.C13', 'Identifier les déclencheurs personnels d''impulsivité', 'Repérer ses propres déclencheurs d''impulsivité (situations, émotions, moments), pour les anticiper.'),
  ('wts:s09c14', 'framework:wts', '1', 'WTS-S09.C14', 'Utiliser une checklist émotionnelle', 'Utiliser une checklist dédiée à l''état émotionnel pour objectiver son état avant et pendant la séance.'),
  ('wts:s09c15', 'framework:wts', '1', 'WTS-S09.C15', 'Documenter une erreur comportementale', 'Consigner honnêtement ses erreurs de comportement (impulsion, entorse à une règle), pour pouvoir les corriger.'),
  ('wts:s09c16', 'framework:wts', '1', 'WTS-S09.C16', 'Suivre une correction comportementale validée', 'Mettre en œuvre dans la durée une correction comportementale définie avec le coach, et en suivre l''effet.'),
  ('wts:s09c17', 'framework:wts', '1', 'WTS-S09.C17', 'Respecter une limite personnelle de fatigue', 'Reconnaître sa fatigue et s''arrêter avant qu''elle ne dégrade ses décisions.'),
  ('wts:s09c18', 'framework:wts', '1', 'WTS-S09.C18', 'Demander de l''aide avant escalation', 'Solliciter le coach ou un tiers avant qu''une difficulté comportementale ne dégénère, plutôt que de s''isoler.'),
  ('wts:s09c19', 'framework:wts', '1', 'WTS-S09.C19', 'Reconnaître une session non tradable pour soi', 'Décider de ne pas trader une session quand son état ou le contexte personnel ne le permet pas.'),
  ('wts:s09c20', 'framework:wts', '1', 'WTS-S09.C20', 'Faire un débrief émotionnel honnête', 'Mener après la séance un débrief émotionnel sincère, sans se mentir sur ses réactions.'),
  ('wts:s10c01', 'framework:wts', '1', 'WTS-S10.C01', 'Définir une priorité de progression hebdomadaire', 'Choisir chaque semaine une priorité de progression claire, pour concentrer ses efforts plutôt que se disperser.'),
  ('wts:s10c02', 'framework:wts', '1', 'WTS-S10.C02', 'Suivre une mission jusqu''à validation', 'Mener une mission d''entraînement jusqu''à sa validation, sans l''abandonner en cours de route.'),
  ('wts:s10c03', 'framework:wts', '1', 'WTS-S10.C03', 'Demander une preuve ou un retour précis', 'Formuler des demandes précises de preuve ou de retour, pour obtenir un accompagnement réellement utile.'),
  ('wts:s10c04', 'framework:wts', '1', 'WTS-S10.C04', 'Appliquer un feedback coach sans dispersion', 'Mettre en œuvre un feedback du coach de façon ciblée, sans se disperser sur trop de choses à la fois.'),
  ('wts:s10c05', 'framework:wts', '1', 'WTS-S10.C05', 'Consolider une compétence avant d''en ajouter une autre', 'Stabiliser une compétence avant d''en travailler une nouvelle, pour construire sur des bases solides.'),
  ('wts:s10c06', 'framework:wts', '1', 'WTS-S10.C06', 'Mesurer sa progression sur une période', 'Évaluer objectivement sa progression sur une période, à partir de données et non d''impressions.'),
  ('wts:s10c07', 'framework:wts', '1', 'WTS-S10.C07', 'Construire un plan d''amélioration autonome', 'Élaborer seul un plan d''amélioration cohérent, signe d''autonomie dans son apprentissage.'),
  ('wts:s10c08', 'framework:wts', '1', 'WTS-S10.C08', 'Préparer la prochaine phase d''accompagnement', 'Anticiper et préparer la suite de son parcours d''accompagnement, en identifiant ses besoins.'),
  ('wts:s11c02', 'framework:wts', '1', 'WTS-S11.C02', 'Hiérarchiser l''impact attendu d''un événement', 'Estimer l''importance relative des événements macro du jour pour savoir lesquels peuvent réellement affecter la séance.'),
  ('wts:s11c03', 'framework:wts', '1', 'WTS-S11.C03', 'Définir le couloir horaire de travail de la journée', 'Déterminer, en fonction du contexte macro et des événements, les plages horaires où l''on va effectivement travailler.'),
  ('wts:s11c04', 'framework:wts', '1', 'WTS-S11.C04', 'Anticiper un type de journée à partir du contexte', 'Formuler, avant la séance, une hypothèse sur le type de journée attendu (calme, directionnelle, piégeuse) à partir du contexte.'),
  ('wts:s11c05', 'framework:wts', '1', 'WTS-S11.C05', 'Lire la tendance du dollar index', 'Suivre la tendance générale de l''indice dollar et comprendre son influence possible sur les instruments tradés.'),
  ('wts:s11c06', 'framework:wts', '1', 'WTS-S11.C06', 'Lire le niveau et la direction des taux d''intérêt', 'Comprendre le niveau et la direction des taux d''intérêt et leur rôle dans l''environnement de marché.'),
  ('wts:s11c07', 'framework:wts', '1', 'WTS-S11.C07', 'Relier une lecture macro à son instrument', 'Faire le lien entre une lecture macroéconomique et son effet concret et plausible sur l''instrument que l''on trade.'),
  ('wts:s11c08', 'framework:wts', '1', 'WTS-S11.C08', 'Distinguer ce qui informe et ce qui déclenche', 'Faire la différence entre une information de contexte (qui informe) et un élément déclencheur d''action (qui déclenche), pour ne pas confondre analyse et signal.');
insert into public.wsp_skill_levels
  (id, skill_id, framework_version, slug, label, rank, criteria, observation_min, observation_max) values
  ('wts:s01c01#aware', 'wts:s01c01', '1', 'aware', 'Aware', 1, 'Observé : Sur un cas fourni, nomme au moins trois catégories d''acteurs et décrit brièvement leur rôle — Preuve attendue : Réponse écrite ou orale sur le cas fourni, validée par le coach', 2, 2),
  ('wts:s01c01#applied', 'wts:s01c01', '1', 'applied', 'Applied', 2, 'Observé : Relie seul, sur ses propres observations de séance, un mouvement de prix à un type d''acteur plausible et justifie — Preuve attendue : Note de séance où l''élève associe un mouvement à un comportement d''acteur', 3, 3),
  ('wts:s01c01#proficient', 'wts:s01c01', '1', 'proficient', 'Proficient', 3, 'Observé : Intègre cette lecture des acteurs dans son analyse sur au moins 5 séances, de façon cohérente — Preuve attendue : 5 analyses datées mentionnant l''influence des acteurs', 4, 4),
  ('wts:s01c01#mastery', 'wts:s01c01', '1', 'mastery', 'Mastery', 4, 'Observé : Nuance sa lecture selon le contexte (séance calme, annonce, ouverture) et corrige ses interprétations erronées — Preuve attendue : Revue de séance montrant une interprétation ajustée + mission validée', 5, 5),
  ('wts:s01c02#aware', 'wts:s01c02', '1', 'aware', 'Aware', 1, 'Observé : Explique, sur un exemple fourni, ce que représentent les niveaux du carnet et la différence offre/demande — Preuve attendue : Explication écrite ou orale sur l''exemple fourni', 2, 2),
  ('wts:s01c02#applied', 'wts:s01c02', '1', 'applied', 'Applied', 2, 'Observé : Décrit seul, sur ses propres observations, ce que le carnet indique à un moment donné et ce qu''il ne dit pas — Preuve attendue : Capture commentée d''une observation du carnet en préparation ou séance', 3, 3),
  ('wts:s01c02#proficient', 'wts:s01c02', '1', 'proficient', 'Proficient', 3, 'Observé : Utilise cette lecture du carnet pour éclairer ses décisions sur au moins 5 séances réelles, sans sur-interpréter — Preuve attendue : 5 séances documentées reliant lecture du carnet et décision', 4, 4),
  ('wts:s01c02#mastery', 'wts:s01c02', '1', 'mastery', 'Mastery', 4, 'Observé : Distingue les situations où le carnet est fiable de celles où il trompe, l''explique et corrige ses lectures — Preuve attendue : Revue commentée illustrant une lecture nuancée + mission validée', 5, 5),
  ('wts:s01c03#aware', 'wts:s01c03', '1', 'aware', 'Aware', 1, 'Observé : Décrit correctement les trois types d''ordres et leur effet sur un cas fourni — Preuve attendue : Réponse validée sur le cas fourni', 2, 2),
  ('wts:s01c03#applied', 'wts:s01c03', '1', 'applied', 'Applied', 2, 'Observé : Choisit seul le type d''ordre adapté à une situation de son propre plan et justifie — Preuve attendue : Plan ou note où le choix d''ordre est explicité et justifié', 3, 3),
  ('wts:s01c03#proficient', 'wts:s01c03', '1', 'proficient', 'Proficient', 3, 'Observé : Emploie le bon type d''ordre de façon cohérente sur au moins 5 séances réelles — Preuve attendue : 5 séances documentées montrant des choix d''ordres cohérents', 4, 4),
  ('wts:s01c03#mastery', 'wts:s01c03', '1', 'mastery', 'Mastery', 4, 'Observé : Adapte son choix d''ordre selon les conditions (liquidité, volatilité), l''explique et corrige ses erreurs d''exécution — Preuve attendue : Revue montrant une adaptation raisonnée + mission validée', 5, 5),
  ('wts:s01c04#aware', 'wts:s01c04', '1', 'aware', 'Aware', 1, 'Observé : Nomme les contrats étudiés et leurs caractéristiques de base sur un support fourni — Preuve attendue : Réponse validée sur le support fourni', 2, 2),
  ('wts:s01c04#applied', 'wts:s01c04', '1', 'applied', 'Applied', 2, 'Observé : Identifie seul le contrat pertinent pour son propre plan et justifie son choix — Preuve attendue : Note de préparation mentionnant le contrat choisi et pourquoi', 3, 3),
  ('wts:s01c04#proficient', 'wts:s01c04', '1', 'proficient', 'Proficient', 3, 'Observé : Travaille de façon cohérente avec le(s) contrat(s) adapté(s) sur au moins 5 séances — Preuve attendue : 5 séances documentées avec le contrat approprié', 4, 4),
  ('wts:s01c04#mastery', 'wts:s01c04', '1', 'mastery', 'Mastery', 4, 'Observé : Choisit le contrat selon le contexte (session, volatilité), l''explique et ajuste si nécessaire — Preuve attendue : Revue justifiant un choix de contrat contextuel + mission validée', 5, 5),
  ('wts:s01c05#aware', 'wts:s01c05', '1', 'aware', 'Aware', 1, 'Observé : Calcule correctement, sur un cas fourni, la valeur d''un tick et d''un point — Preuve attendue : Calcul validé sur le cas fourni', 2, 2),
  ('wts:s01c05#applied', 'wts:s01c05', '1', 'applied', 'Applied', 2, 'Observé : Calcule seul ces valeurs pour son propre contrat et les relie à un montant de risque — Preuve attendue : Note ou calcul personnel reliant tick/point à un montant', 3, 3),
  ('wts:s01c05#proficient', 'wts:s01c05', '1', 'proficient', 'Proficient', 3, 'Observé : Intègre ces calculs dans sa gestion sur au moins 5 séances, sans erreur d''unité — Preuve attendue : 5 séances où le dimensionnement s''appuie sur ces valeurs', 4, 4),
  ('wts:s01c05#mastery', 'wts:s01c05', '1', 'mastery', 'Mastery', 4, 'Observé : Manie ces conversions avec aisance dans des situations variées, les explique et corrige toute erreur d''unité — Preuve attendue : Revue montrant une maîtrise des conversions + mission validée', 5, 5),
  ('wts:s01c06#aware', 'wts:s01c06', '1', 'aware', 'Aware', 1, 'Observé : Décrit, sur une séance fournie, où le volume est élevé ou faible et ce que cela peut signifier — Preuve attendue : Séance annotée fournie, commentée par l''élève', 2, 2),
  ('wts:s01c06#applied', 'wts:s01c06', '1', 'applied', 'Applied', 2, 'Observé : Repère seul les zones de volume marquant sur sa propre séance et en tire une lecture — Preuve attendue : Capture de sa séance avec les zones de volume annotées', 3, 3),
  ('wts:s01c06#proficient', 'wts:s01c06', '1', 'proficient', 'Proficient', 3, 'Observé : Utilise la lecture du volume pour éclairer ses scénarios sur au moins 5 séances réelles — Preuve attendue : 5 séances reliant lecture du volume et scénario', 4, 4),
  ('wts:s01c06#mastery', 'wts:s01c06', '1', 'mastery', 'Mastery', 4, 'Observé : Interprète le volume en contexte (comparaison à l''habituel, moment de séance), l''explique et corrige ses erreurs — Preuve attendue : Revue montrant une lecture contextuelle du volume + mission validée', 5, 5),
  ('wts:s01c07#aware', 'wts:s01c07', '1', 'aware', 'Aware', 1, 'Observé : Explique, sur un cas fourni, la différence entre liquidité disponible et absorbée — Preuve attendue : Explication validée sur le cas fourni', 2, 2),
  ('wts:s01c07#applied', 'wts:s01c07', '1', 'applied', 'Applied', 2, 'Observé : Repère seul, sur ses observations, un moment d''absorption ou de disponibilité et l''interprète — Preuve attendue : Observation commentée d''un épisode de liquidité', 3, 3),
  ('wts:s01c07#proficient', 'wts:s01c07', '1', 'proficient', 'Proficient', 3, 'Observé : Intègre cette lecture de la liquidité dans ses décisions sur au moins 5 séances réelles — Preuve attendue : 5 séances documentées reliant liquidité et décision', 4, 4),
  ('wts:s01c07#mastery', 'wts:s01c07', '1', 'mastery', 'Mastery', 4, 'Observé : Distingue finement les dynamiques de liquidité selon le contexte, l''explique et corrige ses lectures erronées — Preuve attendue : Revue illustrant une lecture nuancée + mission validée', 5, 5),
  ('wts:s01c08#aware', 'wts:s01c08', '1', 'aware', 'Aware', 1, 'Observé : Situe correctement, sur un support fourni, les principaux horaires clés et leur importance — Preuve attendue : Réponse validée sur le support fourni', 2, 2),
  ('wts:s01c08#applied', 'wts:s01c08', '1', 'applied', 'Applied', 2, 'Observé : Organise seul sa préparation en tenant compte de ces horaires et le justifie — Preuve attendue : Note de préparation tenant compte des horaires clés', 3, 3),
  ('wts:s01c08#proficient', 'wts:s01c08', '1', 'proficient', 'Proficient', 3, 'Observé : Adapte son activité aux horaires clés de façon cohérente sur au moins 5 séances — Preuve attendue : 5 séances où l''activité respecte les horaires clés', 4, 4),
  ('wts:s01c08#mastery', 'wts:s01c08', '1', 'mastery', 'Mastery', 4, 'Observé : Ajuste finement son comportement selon les horaires et le contexte, l''explique et corrige ses écarts — Preuve attendue : Revue montrant une gestion fine des horaires + mission validée', 5, 5),
  ('wts:s01c09#aware', 'wts:s01c09', '1', 'aware', 'Aware', 1, 'Observé : Classe correctement, sur des cas fournis, des séances en tendance, range ou rotation — Preuve attendue : Cas fournis classés et justifiés', 2, 2),
  ('wts:s01c09#applied', 'wts:s01c09', '1', 'applied', 'Applied', 2, 'Observé : Identifie seul le régime de sa propre séance et en tire une implication pour son plan — Preuve attendue : Note de séance identifiant le régime et son implication', 3, 3),
  ('wts:s01c09#proficient', 'wts:s01c09', '1', 'proficient', 'Proficient', 3, 'Observé : Reconnaît le régime de marché de façon fiable sur au moins 5 séances réelles — Preuve attendue : 5 séances documentées avec identification du régime', 4, 4),
  ('wts:s01c09#mastery', 'wts:s01c09', '1', 'mastery', 'Mastery', 4, 'Observé : Détecte les changements de régime en séance, l''explique et corrige ses erreurs de classification — Preuve attendue : Revue montrant une détection de changement de régime + mission validée', 5, 5),
  ('wts:s01c10#aware', 'wts:s01c10', '1', 'aware', 'Aware', 1, 'Observé : Nomme et situe le POC, la Value Area et les zones de fort et faible volume sur un graphique fourni — Preuve attendue : Graphique annoté fourni par le coach', 2, 2),
  ('wts:s01c10#applied', 'wts:s01c10', '1', 'applied', 'Applied', 2, 'Observé : Repère seul ces niveaux sur son propre graphique en préparation et dit ce qu''ils signifient — Preuve attendue : Capture de sa préparation de séance', 3, 3),
  ('wts:s01c10#proficient', 'wts:s01c10', '1', 'proficient', 'Proficient', 3, 'Observé : Utilise ces niveaux pour construire ses scénarios sur au moins 5 séances réelles, avec cohérence — Preuve attendue : 5 préparations datées et trades liés', 4, 4),
  ('wts:s01c10#mastery', 'wts:s01c10', '1', 'mastery', 'Mastery', 4, 'Observé : Adapte sa lecture quand la structure du profil change en séance, l''explique et corrige ses erreurs — Preuve attendue : Revue de séance commentée et mission validée', 5, 5),
  ('wts:s02c01#aware', 'wts:s02c01', '1', 'aware', 'Aware', 1, 'Observé : Décrit, sur une séance fournie, les grandes phases de la structure intraday — Preuve attendue : Séance annotée fournie, commentée', 2, 2),
  ('wts:s02c01#applied', 'wts:s02c01', '1', 'applied', 'Applied', 2, 'Observé : Repère seul la structure de sa propre séance et en tire une lecture pour son plan — Preuve attendue : Capture de sa séance avec la structure annotée', 3, 3),
  ('wts:s02c01#proficient', 'wts:s02c01', '1', 'proficient', 'Proficient', 3, 'Observé : Utilise la structure intraday pour ses scénarios sur au moins 5 séances réelles — Preuve attendue : 5 séances reliant structure et scénario', 4, 4),
  ('wts:s02c01#mastery', 'wts:s02c01', '1', 'mastery', 'Mastery', 4, 'Observé : Réévalue la structure quand elle évolue en séance, l''explique et corrige ses erreurs de lecture — Preuve attendue : Revue montrant une réévaluation de structure + mission validée', 5, 5),
  ('wts:s02c02#aware', 'wts:s02c02', '1', 'aware', 'Aware', 1, 'Observé : Sur un graphique fourni, nomme et situe au moins deux zones de liquidité visibles et dit pourquoi — Preuve attendue : Graphique annoté fourni, commenté par l''élève', 2, 2),
  ('wts:s02c02#applied', 'wts:s02c02', '1', 'applied', 'Applied', 2, 'Observé : Repère seul ces zones sur son propre graphique en préparation et explique leur implication (attente, cible, invalidation) — Preuve attendue : Capture de préparation avec zones annotées', 3, 3),
  ('wts:s02c02#proficient', 'wts:s02c02', '1', 'proficient', 'Proficient', 3, 'Observé : Utilise ces zones pour construire ses scénarios sur au moins 5 séances réelles, avec cohérence — Preuve attendue : 5 préparations datées + revue reliant zones et déroulé', 4, 4),
  ('wts:s02c02#mastery', 'wts:s02c02', '1', 'mastery', 'Mastery', 4, 'Observé : Réévalue ses zones quand la liquidité est consommée ou recréée en séance, l''explique et corrige ses erreurs — Preuve attendue : Revue montrant une réévaluation + mission validée', 5, 5),
  ('wts:s02c03#aware', 'wts:s02c03', '1', 'aware', 'Aware', 1, 'Observé : Situe, sur un graphique fourni, au moins une zone de faible volume et explique son sens — Preuve attendue : Graphique annoté fourni, commenté', 2, 2),
  ('wts:s02c03#applied', 'wts:s02c03', '1', 'applied', 'Applied', 2, 'Observé : Repère seul ces zones sur son propre graphique et en tire une implication — Preuve attendue : Capture de préparation avec zones de faible volume annotées', 3, 3),
  ('wts:s02c03#proficient', 'wts:s02c03', '1', 'proficient', 'Proficient', 3, 'Observé : Intègre ces zones dans ses scénarios sur au moins 5 séances réelles — Preuve attendue : 5 séances reliant zones de faible volume et scénario', 4, 4),
